// Los emisores mandan el DTE como adjunto .json (obligatorio) junto al PDF.
// Se ignora todo lo demás: publicidad, estados de cuenta, respuestas.
const salida = [];

for (const item of $input.all()) {
  const binarios = item.binary ?? {};
  for (const clave of Object.keys(binarios)) {
    const b = binarios[clave];
    const nombre = (b.fileName ?? '').toLowerCase();
    const esJson = nombre.endsWith('.json') || b.mimeType === 'application/json';
    if (!esJson) continue;

    let texto;
    try {
      texto = Buffer.from(b.data, 'base64').toString('utf8');
    } catch { continue; }

    let dte;
    try { dte = JSON.parse(texto); } catch { continue; }

    // Un DTE siempre trae identificacion.codigoGeneracion. Si no lo tiene,
    // es otro JSON cualquiera y no nos sirve.
    if (!dte?.identificacion?.codigoGeneracion) continue;

    salida.push({ json: { dte, archivo: b.fileName, asunto: item.json.subject ?? null } });
  }
}

return salida;

